// Normalize an incident signal into fn_create_improvement_proposal params.
// Input (WF_SENTRY_OBSERVER propose_fix / WF_DRIFT_OBSERVER):
//   { app, signal_type:'sentry'|'drift', exception_class?, release?, pattern?, drift_kind?, story_id?, evidence? }
const body = $input.first().json.body || $input.first().json;
const signal = String(body.signal_type || (body.drift_kind ? 'drift' : 'sentry')).toLowerCase();
const app = body.app || 'unknown';
const category = signal === 'drift' ? 'infrastructure_drift' : 'bug_fix';
const key = body.exception_class || body.drift_kind || body.pattern || 'unknown';
const anomaly_key = signal + ':' + app + ':' + key;
const title = '[' + signal + '] ' + app + ' — ' + key;
let desc = 'Incident-driven fix proposal from ' + signal + ' observer.\nApp: ' + app;
if (body.release) desc += '\nRelease: ' + body.release;
if (body.exception_class) desc += '\nException: ' + body.exception_class;
if (body.pattern) desc += '\nPattern: ' + body.pattern;
if (body.evidence) desc += '\nEvidence: ' + JSON.stringify(body.evidence);
return { json: {
  agent_slug: body.agent_slug || 'dirigent',
  category, title, description: desc,
  metadata: { anomaly_key, signal_type: signal, app, story_id: body.story_id || null,
    exception_class: body.exception_class || null, drift_kind: body.drift_kind || null,
    release: body.release || null, source: 'wf_fix_proposer' }
}};
